import {uid,dateKey,addDays,RULE_VERSION} from './engine.js';
let db;
export async function openStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('asha-sahayak-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('workspace');request.onsuccess=()=>{db=request.result;resolve();};request.onerror=()=>reject(request.error);});}
export async function readState(){return new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function writeState(state){return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(state,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage transaction aborted'));});}
